// Rechnet die kompletten KDP-Cover-Masse aus Seitenzahl, Trimmgroesse und Papier.
// Formeln nach KDP: Ruecken = Seitenzahl x Papierdicke, Anschnitt 0,125 Zoll aussen.
// Standard ist 6 x 9 Zoll - das ist das Format der Master-Dokumente.

const f = $('Start').first().json;
const buchId = String(f['Buch-ID'] == null ? '' : f['Buch-ID']).trim();
const seiten = Number(String(f['Seitenzahl'] == null ? '' : f['Seitenzahl']).replace(',', '.'));
const trimWahl = String(f['Trimmgroesse'] == null ? '' : f['Trimmgroesse']);
const papier = String(f['Papier'] == null ? 'Weiss' : f['Papier']);

if (!buchId) throw new Error('Buch-ID fehlt.');
if (!Number.isFinite(seiten) || seiten < 24) throw new Error('Seitenzahl fehlt oder ist unplausibel. KDP-Minimum ist 24 Seiten.');
if (seiten > 828) throw new Error('Seitenzahl ueber dem KDP-Maximum von 828.');

const TRIM = {
  '12,7 x 20,32 cm (5 x 8 Zoll)': [5, 8],
  '13,34 x 20,32 cm (5,25 x 8 Zoll)': [5.25, 8],
  '13,97 x 21,59 cm (5,5 x 8,5 Zoll)': [5.5, 8.5],
  '15,24 x 22,86 cm (6 x 9 Zoll)': [6, 9]
};
const masse = TRIM[trimWahl] || TRIM['15,24 x 22,86 cm (6 x 9 Zoll)'];
const trimB = masse[0];
const trimH = masse[1];

const dicke = papier.toLowerCase().indexOf('creme') !== -1 ? 0.0025 : 0.002252;
const bleed = 0.125;
const ruecken = seiten * dicke;

const gesamtB = 2 * trimB + ruecken + 2 * bleed;
const gesamtH = trimH + 2 * bleed;

let zeile = null;
for (const r of $input.all()) {
  const x = r.json || {};
  if (String(x['Buch-ID'] == null ? '' : x['Buch-ID']).trim() === buchId) { zeile = x; break; }
}
if (!zeile) throw new Error('Buch-ID ' + buchId + ' steht nicht im Buch-Master.');

const s = function (v) { return String(v == null ? '' : v).trim(); };
const ordner = s(zeile['Ordner-ID']);
if (!ordner) throw new Error('Buch ' + buchId + ' hat keine Ordner-ID im Buch-Master.');

return [{ json: {
  buch_id: buchId,
  titel: s(zeile['Buchtitel']),
  untertitel: s(zeile['Untertitel']),
  autor: s(zeile['Pseudonym (Autor)']),
  klappentext: s(zeile['Klappentext']) || s(zeile['Beschreibung']),
  ordner_id: ordner,
  seitenzahl: seiten,
  papier: papier,
  trim_breite_in: trimB,
  trim_hoehe_in: trimH,
  bleed_in: bleed,
  ruecken_in: Number(ruecken.toFixed(4)),
  ruecken_mm: Number((ruecken * 25.4).toFixed(2)),
  gesamt_breite_in: Number(gesamtB.toFixed(4)),
  gesamt_hoehe_in: Number(gesamtH.toFixed(4)),
  ruecken_text_erlaubt: seiten >= 100
}}];

const b = $('Buch waehlen').first().json;
const item = $input.first();

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/jpeg';
const img = 'data:' + mime + ';base64,' + buf.toString('base64');

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const W = b.gesamt_breite_in;
const H = b.gesamt_hoehe_in;
const S = b.ruecken_in;
const BL = b.bleed_in;
const panel = b.trim_breite_in + BL;

// Barcode-Freiflaeche: KDP druckt dort den Code. 2 x 1,2 Zoll, 0,25 Zoll vom Beschnitt entfernt.
const bcB = 2, bcH = 1.2;
const bcLinks = panel - 0.25 - bcB;
const bcOben = H - BL - 0.25 - bcH;

// --- Klappentext in Absaetze zerlegen -------------------------------------
// 1. Vorhandene Absaetze aus dem Sheet werden uebernommen (Leerzeile = Absatz),
//    einzelne Zeilenumbrueche zaehlen als Leerzeichen.
// 2. Nur wenn der Text gar keine Absaetze hat, wird nach Saetzen gruppiert.
//    Die Satzerkennung verlangt ein Satzzeichen mit mindestens zwei Zeichen
//    davor und einem Grossbuchstaben danach. Ein schliessendes Anfuehrungs-
//    zeichen allein trennt NICHT mehr - genau das hat vorher mitten im Satz
//    einen neuen Absatz erzeugt.

const roh = String(b.klappentext || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();

let bloecke = roh.split(/\n\s*\n+/)
  .map(function (t) { return t.replace(/\s+/g, ' ').trim(); })
  .filter(function (t) { return t.length > 0; });

if (bloecke.length <= 1) {
  const text = bloecke.length ? bloecke[0] : '';
  bloecke = [];
  if (text) {
    const saetze = text.split(/(?<=[a-zäöüß0-9)”“»"']{2}[.!?][”“»"']?)\s+(?=[A-ZÄÖÜ„»])/);
    for (const satz of saetze) {
      if (!bloecke.length || (bloecke[bloecke.length - 1] + ' ' + satz).length > 300) bloecke.push(satz);
      else bloecke[bloecke.length - 1] += ' ' + satz;
    }
  }
}

const MAX = 1100;
const absaetze = [];
let gesamt = 0;
for (const p of bloecke) {
  if (gesamt + p.length > MAX) {
    const rest = MAX - gesamt;
    if (rest > 80) absaetze.push(p.slice(0, rest).replace(/\s\S*$/, '') + '...');
    break;
  }
  absaetze.push(p);
  gesamt += p.length + 1;
}
// -------------------------------------------------------------------------

const rueckenBlock = b.ruecken_text_erlaubt
  ? '<div class="spinetext"><span class="st">' + esc(b.titel) + '</span><span class="sa">' + esc(b.autor) + '</span></div>'
  : '';

const css = '@page { size: ' + W + 'in ' + H + 'in; margin: 0; }'
  + '* { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }'
  + 'html, body { margin:0; padding:0; width:' + W + 'in; height:' + H + 'in; overflow:hidden;'
  + ' font-family: "DejaVu Serif", Georgia, "Times New Roman", serif; color:#fff; }'
  + '.sheet { position:relative; width:' + W + 'in; height:' + H + 'in; overflow:hidden;'
  + ' page-break-inside:avoid; break-inside:avoid; }'
  + '.bg { position:absolute; left:-0.3in; top:-0.3in; width:' + (W + 0.6) + 'in; height:' + (H + 0.6) + 'in;'
  + ' background-image:url("' + img + '"); background-size:cover; background-position:center;'
  + ' filter: blur(28px) saturate(1.15) brightness(0.42); }'
  + '.tint { position:absolute; left:0; top:0; width:' + W + 'in; height:' + H + 'in;'
  + ' background:linear-gradient(180deg, rgba(0,0,0,0.30), rgba(0,0,0,0.55)); }'
  + '.back { position:absolute; left:0; top:0; width:' + panel + 'in; height:' + H + 'in;'
  + ' padding:' + (BL + 0.55) + 'in 0.45in ' + (BL + 0.35) + 'in ' + (BL + 0.45) + 'in; overflow:hidden; }'
  + '.btitel { font-size:17pt; line-height:1.15; margin:0 0 0.06in 0; font-weight:700; }'
  + '.buntertitel { font-size:10.5pt; line-height:1.25; margin:0 0 0.22in 0; opacity:0.88; font-style:italic; }'
  + '.regel { width:0.9in; height:2px; background:rgba(255,255,255,0.55); margin:0 0 0.2in 0; }'
  + '.btext { max-height:' + (H - 2 * BL - 3.0) + 'in; overflow:hidden; }'
  + '.btext p { font-size:9.6pt; line-height:1.42; margin:0 0 0.11in 0; opacity:0.95; }'
  + '.bautor { position:absolute; left:' + (BL + 0.45) + 'in; bottom:' + (BL + 0.35) + 'in;'
  + ' font-size:10pt; letter-spacing:0.5pt; text-transform:uppercase; opacity:0.85; }'
  + '.barcode { position:absolute; left:' + bcLinks + 'in; top:' + bcOben + 'in; width:' + bcB + 'in; height:' + bcH + 'in;'
  + ' background:#ffffff; border-radius:2pt; }'
  + '.spine { position:absolute; left:' + panel + 'in; top:0; width:' + S + 'in; height:' + H + 'in;'
  + ' background:rgba(0,0,0,0.28); overflow:hidden;'
  + ' box-shadow: inset 1px 0 0 rgba(255,255,255,0.10), inset -1px 0 0 rgba(255,255,255,0.10); }'
  + '.spinetext { position:absolute; left:50%; top:50%; width:' + (H - 1.0) + 'in; height:' + S + 'in;'
  + ' transform: translate(-50%,-50%) rotate(90deg); display:flex; align-items:center;'
  + ' justify-content:space-between; padding:0 0.15in; }'
  + '.st { font-size:' + Math.max(7, Math.min(12, S * 26)).toFixed(1) + 'pt; font-weight:700; white-space:nowrap;'
  + ' overflow:hidden; text-overflow:ellipsis; max-width:72%; }'
  + '.sa { font-size:' + Math.max(6, Math.min(9.5, S * 20)).toFixed(1) + 'pt; white-space:nowrap; opacity:0.9; }'
  + '.front { position:absolute; left:' + (panel + S) + 'in; top:0; width:' + panel + 'in; height:' + H + 'in; overflow:hidden; }'
  + '.front img { width:100%; height:100%; object-fit:cover; object-position:center; display:block; }';

const html = '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><style>' + css + '</style></head><body>'
  + '<div class="sheet">'
  + '<div class="bg"></div><div class="tint"></div>'
  + '<div class="back">'
  + '<div class="btitel">' + esc(b.titel) + '</div>'
  + (b.untertitel ? '<div class="buntertitel">' + esc(b.untertitel) + '</div>' : '')
  + '<div class="regel"></div>'
  + '<div class="btext">' + absaetze.map(function (p) { return '<p>' + esc(p) + '</p>'; }).join('') + '</div>'
  + '<div class="bautor">' + esc(b.autor) + '</div>'
  + '<div class="barcode"></div>'
  + '</div>'
  + '<div class="spine">' + rueckenBlock + '</div>'
  + '<div class="front"><img src="' + img + '"></div>'
  + '</div>'
  + '</body></html>';

const sauberTitel = String(b.titel).replace(/[^a-zA-Z0-9äöüÄÖÜß\- ]/g, '').trim().slice(0, 50);

return [{ json: {
  html: html,
  absaetze: absaetze.length,
  klappentext_zeichen: gesamt,
  dateiname: 'PRINT_COVER_' + sauberTitel + '_' + $now.toFormat('yyyy-MM-dd') + '.pdf'
} }];
